using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Text;

namespace EnusDE.Signaltechnik {
    public sealed class PlanNode {public string Id,Common,Normal;public double X,Y;public bool Point;}
    public sealed class PlanEdge {public string Id,A,B;public double Length;}
    public sealed class PlanCut {public string Segment,Signal;public double Meters,X,Y;}
    public sealed class NetworkInput {public string World;public List<PlanNode> Nodes=new List<PlanNode>();public List<PlanEdge> Edges=new List<PlanEdge>();public List<PlanCut> Cuts=new List<PlanCut>();}
    public sealed class NetworkResult {public PanelDocument Panel;public Dictionary<string,TrackBlock> Blocks=new Dictionary<string,TrackBlock>();public int Segments,Chains,Drawn;public List<string> Missing=new List<string>();}
    public static class NetworkPlan {
        sealed class Piece {public string A,B;public TrackSection S;}
        sealed class Chain {public string A,B;public TrackBlock Block;}
        sealed class Cell {public int X,Y;public Cell(int x,int y){X=x;Y=y;}public int Key=>Y*512+X;}
        public static NetworkResult Build(NetworkInput input,CancellationToken cancel=default,bool draw=true,int attempt=0) {
            if(input.Nodes.Count>20000||input.Edges.Count>24000)throw new InvalidOperationException("Gleisnetz überschreitet die Prototypgrenze.");
            var nodes=input.Nodes.ToDictionary(n=>n.Id);var adjacency=nodes.Keys.ToDictionary(id=>id,id=>new List<Piece>());var pieces=new List<Piece>();
            foreach(var e in input.Edges.OrderBy(e=>e.Id,StringComparer.Ordinal)){cancel.ThrowIfCancellationRequested();if(!nodes.ContainsKey(e.A)||!nodes.ContainsKey(e.B)||e.Length<=.01||double.IsNaN(e.Length))throw new InvalidOperationException("Ungültiges Gleisnetz.");var cuts=input.Cuts.Where(c=>c.Segment==e.Id&&c.Meters>.001&&c.Meters<e.Length-.001).OrderBy(c=>c.Meters).GroupBy(c=>Math.Round(c.Meters,3)).Select(g=>g.First()).ToArray();string last=e.A;double from=0;
                foreach(var cut in cuts){string id="@"+e.Id+":"+cut.Meters.ToString("R",System.Globalization.CultureInfo.InvariantCulture);nodes[id]=new PlanNode{Id=id,X=cut.X,Y=cut.Y};adjacency[id]=new List<Piece>();var p=new Piece{A=last,B=id,S=new TrackSection{Segment=e.Id,From=from,To=cut.Meters}};pieces.Add(p);adjacency[last].Add(p);adjacency[id].Add(p);last=id;from=cut.Meters;}
                var end=new Piece{A=last,B=e.B,S=new TrackSection{Segment=e.Id,From=from,To=e.Length}};pieces.Add(end);adjacency[last].Add(end);adjacency[e.B].Add(end);
            }
            var boundary=new HashSet<string>(adjacency.Where(a=>a.Value.Count!=2||nodes[a.Key].Point||a.Key.StartsWith("@")).Select(a=>a.Key));var visitedNodes=new HashSet<string>();foreach(string start in adjacency.Keys){if(visitedNodes.Contains(start)||adjacency[start].Count==0)continue;var component=new List<string>();var stack=new Stack<string>();stack.Push(start);while(stack.Count>0){string id=stack.Pop();if(!visitedNodes.Add(id))continue;component.Add(id);foreach(var p in adjacency[id])stack.Push(p.A==id?p.B:p.A);}if(!component.Any(boundary.Contains)){boundary.Add(component.OrderBy(id=>id,StringComparer.Ordinal).First());boundary.Add(component.OrderBy(id=>id,StringComparer.Ordinal).Skip(component.Count/2).First());}}
            // A loop returning to one junction needs a second display boundary: two distinct ports.
            foreach(string start in boundary.ToArray())foreach(var first in adjacency[start]){string at=start;var edge=first;var interior=new List<string>();var seen=new HashSet<Piece>();while(seen.Add(edge)){at=edge.A==at?edge.B:edge.A;if(boundary.Contains(at)){if(at==start&&interior.Count>0)boundary.Add(interior[interior.Count/2]);break;}interior.Add(at);edge=adjacency[at].First(p=>!ReferenceEquals(p,edge));}}
            var result=new NetworkResult{Panel=new PanelDocument{WorldKey=input.World,Columns=512,Rows=320},Segments=input.Edges.Count};var used=new HashSet<Piece>();var chains=new List<Chain>();
            foreach(string start in boundary.OrderBy(id=>id,StringComparer.Ordinal))foreach(var first in adjacency[start]){if(used.Contains(first))continue;string current=start;var p=first;var path=new List<DirectedRouteSection>();while(true){if(!used.Add(p))throw new InvalidOperationException("Mehrdeutige Gleiskette.");bool reverse=p.B==current;path.Add(new DirectedRouteSection{Section=p.S,Reverse=reverse});current=reverse?p.A:p.B;if(boundary.Contains(current))break;p=adjacency[current].First(next=>!ReferenceEquals(next,p));}
                string forward=string.Join("|",path.Select(s=>s.Section.Key+":"+s.Reverse)),backward=string.Join("|",path.AsEnumerable().Reverse().Select(s=>s.Section.Key+":"+!s.Reverse));string hash=SharedDocuments.Hash(Encoding.UTF8.GetBytes(string.CompareOrdinal(forward,backward)<0?forward:backward));var block=new TrackBlock{Id="b:"+hash.Substring(0,24),Name="Abschnitt "+(chains.Count+1),Path=path};block.Validate();result.Blocks.Add(block.Id,block);chains.Add(new Chain{A=start,B=current,Block=block});}
            if(used.Count!=pieces.Count)throw new InvalidOperationException("Nicht alle Gleissegmente wurden erfasst.");result.Chains=chains.Count;
            foreach(var n in input.Nodes.Where(n=>n.Point&&adjacency[n.Id].Count>0)){var block=new TrackBlock{Id="p:"+n.Id,Name="Weiche "+n.Id,Point=n.Id};foreach(var p in adjacency[n.Id])block.Guards.Add(new TrackSection{Segment=p.S.Segment,From=p.A==n.Id?p.S.From:Math.Max(p.S.From,p.S.To-25),To=p.A==n.Id?Math.Min(p.S.To,p.S.From+25):p.S.To});block.Validate();result.Blocks.Add(block.Id,block);}
            if(!draw||pieces.Count==0)return result;
            var active=boundary.Where(id=>adjacency[id].Count>0).Select(id=>nodes[id]).OrderBy(n=>n.X).ThenBy(n=>n.Y).ThenBy(n=>n.Id,StringComparer.Ordinal).ToArray();if(active.Length>1800)throw new InvalidOperationException("Zu viele Netzgrenzen für eine Grundtafel.");var positions=new Dictionary<string,Cell>();double minX=active.Min(n=>n.X),maxX=active.Max(n=>n.X),minY=active.Min(n=>n.Y),maxY=active.Max(n=>n.Y);
            foreach(var n in active){int x=6+(int)Math.Round((n.X-minX)/Math.Max(1,maxX-minX)*499),y=6+(int)Math.Round((maxY-n.Y)/Math.Max(1,maxY-minY)*307);Cell cell=null;for(int r=0;r<512&&cell==null;r++)for(int dx=-r;dx<=r&&cell==null;dx++)foreach(int dy in r==0?new[]{0}:new[]{-r,r}){int a=x+dx,b=y+dy;if(a<6||a>505||b<6||b>313)continue;if(positions.Values.All(c=>Math.Max(Math.Abs(c.X-a),Math.Abs(c.Y-b))>=9)){cell=new Cell(a,b);break;}}if(cell==null)throw new InvalidOperationException("Kein Platz für alle Weichen und Signalstellen.");positions[n.Id]=cell;}
            var tiles=new Dictionary<int,PanelTile>();var reserved=new HashSet<int>();foreach(var c in positions.Values)for(int x=c.X-2;x<=c.X+2;x++)for(int y=c.Y-2;y<=c.Y+2;y++)reserved.Add(y*512+x);
            var ports=new Dictionary<string,int>();foreach(var n in active){var arms=chains.Where(c=>c.A==n.Id||c.B==n.Id).OrderBy(c=>c.Block.Id,StringComparer.Ordinal).ToArray();var taken=new HashSet<int>();int stem=0,normal=4;if(n.Point){var common=arms.FirstOrDefault(c=>EndSegment(c,n.Id)==n.Common);var neighbor=common==null?null:positions[common.A==n.Id?common.B:common.A];if(neighbor!=null)stem=PanelConnections.Direction(neighbor.X-positions[n.Id].X,neighbor.Y-positions[n.Id].Y);normal=(stem+4)%8;}
                foreach(var c in arms.OrderBy(c=>n.Point&&EndSegment(c,n.Id)==n.Common?0:n.Point&&EndSegment(c,n.Id)==n.Normal?1:2)){var a=positions[n.Id];var other=positions[c.A==n.Id?c.B:c.A];int target=PanelConnections.Direction(other.X-a.X,other.Y-a.Y);if(n.Point){target=EndSegment(c,n.Id)==n.Common?stem:EndSegment(c,n.Id)==n.Normal?normal:(normal+1)%8;}int d=Enumerable.Range(0,8).Where(i=>!taken.Contains(i)).OrderBy(i=>Math.Min((i-target+8)%8,(target-i+8)%8)).First();taken.Add(d);ports[n.Id+"|"+c.Block.Id]=d;}
            }
            foreach(var c in chains.OrderBy(c=>attempt==0?Math.Max(Math.Abs(positions[c.A].X-positions[c.B].X),Math.Abs(positions[c.A].Y-positions[c.B].Y)):attempt==1?-Math.Max(Math.Abs(positions[c.A].X-positions[c.B].X),Math.Abs(positions[c.A].Y-positions[c.B].Y)):Convert.ToInt32(c.Block.Id.Substring(2+(attempt-2)*4,4),16)).ThenBy(c=>c.Block.Id,StringComparer.Ordinal)){cancel.ThrowIfCancellationRequested();var a=positions[c.A];var b=positions[c.B];int da=ports[c.A+"|"+c.Block.Id],db=ports[c.B+"|"+c.Block.Id];var sa=new Cell(a.X+2*PanelConnections.Dx[da],a.Y+2*PanelConnections.Dy[da]);var sb=new Cell(b.X+2*PanelConnections.Dx[db],b.Y+2*PanelConnections.Dy[db]);var path=Route(sa,sb,tiles,reserved,cancel);if(path==null){result.Missing.Add("path:"+c.Block.Id);continue;}path.Insert(0,new Cell(a.X+PanelConnections.Dx[da],a.Y+PanelConnections.Dy[da]));path.Insert(0,a);path.Add(new Cell(b.X+PanelConnections.Dx[db],b.Y+PanelConnections.Dy[db]));path.Add(b);
                bool conflict=false;for(int i=1;i<path.Count-1;i++){PanelTile old;if(!tiles.TryGetValue(path[i].Key,out old))continue;int incoming=PanelConnections.Direction(path[i-1].X-path[i].X,path[i-1].Y-path[i].Y),outgoing=PanelConnections.Direction(path[i+1].X-path[i].X,path[i+1].Y-path[i].Y);int mask=(1<<incoming)|(1<<outgoing);if(old.Kind==PanelTileKind.Switch||old.SecondBlock!=""||(old.Ports&mask)!=0||((incoming+4)%8)!=outgoing){conflict=true;break;}}if(conflict){result.Missing.Add("conflict:"+c.Block.Id);continue;}
                for(int i=0;i<path.Count;i++){var cell=path[i];PanelTile tile;if(!tiles.TryGetValue(cell.Key,out tile))tiles[cell.Key]=tile=new PanelTile{X=cell.X,Y=cell.Y,BlockId=c.Block.Id};else if(tile.BlockId!=c.Block.Id&&i>0&&i<path.Count-1)tile.SecondBlock=c.Block.Id;
                    foreach(int j in new[]{i-1,i+1})if(j>=0&&j<path.Count)tile.Ports|=1<<PanelConnections.Direction(path[j].X-cell.X,path[j].Y-cell.Y);int count=PanelConnections.Count(tile.Ports);tile.Kind=count==3?PanelTileKind.Switch:count==4?PanelTileKind.Cross:PanelTileKind.Straight;var piece=c.Block.Path[Math.Min(c.Block.Path.Count-1,(int)((double)i/path.Count*c.Block.Path.Count))];tile.AutoSegment=piece.Section.Segment;tile.AutoMeters=(piece.Section.From+piece.Section.To)/2;
                }result.Drawn++;
            }
            foreach(var n in active.Where(n=>n.Point)){var cell=positions[n.Id];PanelTile tile;if(!tiles.TryGetValue(cell.Key,out tile))tiles[cell.Key]=tile=new PanelTile{X=cell.X,Y=cell.Y};tile.Kind=PanelTileKind.Switch;tile.Reference=n.Id;tile.BlockId="p:"+n.Id;tile.SecondBlock="";var common=chains.FirstOrDefault(c=>(c.A==n.Id||c.B==n.Id)&&EndSegment(c,n.Id)==n.Common);var normal=chains.FirstOrDefault(c=>(c.A==n.Id||c.B==n.Id)&&EndSegment(c,n.Id)==n.Normal);if(PanelConnections.Count(tile.Ports)!=3)tile.Ports=0;else{if(common!=null)tile.Stem=1<<ports[n.Id+"|"+common.Block.Id];if(normal!=null)tile.Normal=1<<ports[n.Id+"|"+normal.Block.Id];}}
            foreach(var cut in input.Cuts.Where(c=>!string.IsNullOrEmpty(c.Signal))){string id="@"+cut.Segment+":"+cut.Meters.ToString("R",System.Globalization.CultureInfo.InvariantCulture);Cell cell;PanelTile tile;if(positions.TryGetValue(id,out cell)&&tiles.TryGetValue(cell.Key,out tile)&&PanelConnections.Count(tile.Ports)<=2){tile.Kind=PanelTileKind.Signal;tile.Reference=cut.Signal;}}
            result.Panel.Tiles=tiles.Values.OrderBy(t=>t.Y).ThenBy(t=>t.X).ToList();result.Panel.Validate(input.World);if(result.Missing.Count>0&&attempt<1){var other=Build(input,cancel,true,attempt+1);if(other.Missing.Count<result.Missing.Count)return other;}return result;
        }
        static string EndSegment(Chain c,string node)=>node==c.A?c.Block.Path[0].Section.Segment:c.Block.Path[c.Block.Path.Count-1].Section.Segment;
        sealed class Queue {readonly List<Tuple<double,int>> heap=new List<Tuple<double,int>>();public int Count=>heap.Count;public void Push(int state,double f){var t=Tuple.Create(f,state);int i=heap.Count;heap.Add(t);while(i>0){int p=(i-1)/2;if(heap[p].Item1<=f)break;heap[i]=heap[p];i=p;}heap[i]=t;}public int Pop(){int value=heap[0].Item2;var last=heap[heap.Count-1];heap.RemoveAt(heap.Count-1);if(heap.Count>0){int i=0;while(i*2+1<heap.Count){int c=i*2+1;if(c+1<heap.Count&&heap[c+1].Item1<heap[c].Item1)c++;if(heap[c].Item1>=last.Item1)break;heap[i]=heap[c];i=c;}heap[i]=last;}return value;}}
        static List<Cell> Route(Cell a,Cell b,Dictionary<int,PanelTile> tiles,HashSet<int> reserved,CancellationToken cancel) {
            const int width=512,height=320;var open=new Queue();var costs=new Dictionary<int,double>();var prev=new Dictionary<int,int>();var closed=new HashSet<int>();int start=a.Key*8;costs[start]=0;open.Push(start,0);int goal=-1,steps=0;
            while(open.Count>0){if((++steps&4095)==0)cancel.ThrowIfCancellationRequested();if(steps>300000)break;int state=open.Pop();if(!closed.Add(state))continue;int cell=state/8,d=state%8,x=cell%width,y=cell/width;if(cell==b.Key){goal=state;break;}PanelTile current;tiles.TryGetValue(cell,out current);
                for(int dir=0;dir<8;dir++){int nx=x+PanelConnections.Dx[dir],ny=y+PanelConnections.Dy[dir],key=ny*width+nx;if(nx<2||nx>=width-2||ny<2||ny>=height-2||reserved.Contains(key)&&key!=b.Key)continue;if(current!=null&&cell!=a.Key&&(dir!=d||current.SecondBlock!=""))continue;PanelTile target;if(tiles.TryGetValue(key,out target)){if(target.Kind==PanelTileKind.Switch||target.SecondBlock!=""||PanelConnections.Count(target.Ports)!=2||(target.Ports&((1<<dir)|(1<<((dir+4)%8))))!=0)continue;}
                    int next=key*8+dir;double cost=costs[state]+(dir%2==0?1:1.42)+(cell==a.Key||d==dir?0:.45)+(target==null?0:7);double old;if(costs.TryGetValue(next,out old)&&old<=cost)continue;costs[next]=cost;prev[next]=state;open.Push(next,cost+1.03*(Math.Max(Math.Abs(nx-b.X),Math.Abs(ny-b.Y))+.42*Math.Min(Math.Abs(nx-b.X),Math.Abs(ny-b.Y))));
                }
            }if(goal<0)return null;var path=new List<Cell>();int at=goal;while(true){int cell=at/8;path.Add(new Cell(cell%width,cell/width));if(at==start)break;at=prev[at];}path.Reverse();var simple=new List<Cell>();foreach(var cell in path){int repeated=simple.FindIndex(c=>c.Key==cell.Key);if(repeated>=0)simple.RemoveRange(repeated+1,simple.Count-repeated-1);else simple.Add(cell);}return simple;
        }
    }
}
